Fixpoint dlookup (rs : list (Z * list Z)) (x : Z) : option Z :=
  match rs with
  | [] => None
  | (a, bs) :: rs' => if (a <=? x) && (x <? a + Z.of_nat (length bs)) then nth_error bs (Z.to_nat (x - a)) else dlookup rs' x
  end.

Fixpoint dlookupn (rs : list (Z * list Z)) (x : Z) (n : nat) : option (list Z) :=
  match n with
  | O => Some []
  | S n' => match dlookup rs x, dlookupn rs (x + 1) n' with Some b, Some t => Some (b :: t) | _, _ => None end
  end.

Definition dstat_rs (rs : list (Z * list Z)) (m : mem) : Prop :=
  forall x b, 0 <= x < 2 ^ 64 -> dlookup rs x = Some b -> mrd asegs m (wa x) = Some (Z_to_bv 8 b).

Definition dstat (m : mem) : Prop := dstat_rs D_DIAG_A m.

Definition relro0 (m : mem) : Prop := forall i, 0x17e000 <= i < 0x186000 -> m (Z_to_bv 64 i) = None.

Definition LINV_P5 (m : mem) : Prop := relro0 m /\ dstat m.

Lemma rdn_of_dstat_rs : forall rs m n x zs, dstat_rs rs m -> 0 <= x -> x + Z.of_nat n <= 2 ^ 64 ->
  dlookupn rs x n = Some zs -> PropExec.rdn asegs m (Z_to_bv 64 x) n = Some (map (Z_to_bv 8) zs).
