Fixpoint img_b (A : Z) (bs : list byte) : bool :=
  match bs with
  | [] => true
  | b :: bs' => match mrd asegs (fun _ => None) (wa A) with
                | Some b' => bv_eqb b b' && img_b (A + 1) bs'
                | None => false
                end
  end.

Lemma img_b_spec : forall bs A i, img_b A bs = true -> (i < length bs)%nat ->
